from __future__ import annotations

import logging
import time
from collections.abc import Callable
from datetime import UTC, datetime
from pathlib import Path
from typing import Protocol
from uuid import NAMESPACE_URL, uuid5

from catalyst_router.challenger import PublicChallengerStatus, ShadowPrediction
from catalyst_router.domain import DecisionRecord
from catalyst_router.ports import OperationalStore
from catalyst_router.training import FeatureVector, MarketBar, build_feature_vectors
from catalyst_router.universe import DailyUniverse, UniverseSnapshot, UniverseUnavailable

logger = logging.getLogger(__name__)


class MarketData(Protocol):
    def recent_bars(
        self,
        symbols: tuple[str, ...],
        *,
        timeframe_minutes: int,
        lookback_days: int,
    ) -> list[MarketBar]: ...


class ChallengerPredictor(Protocol):
    status: PublicChallengerStatus
    symbols: tuple[str, ...]

    def predict(self, vector: FeatureVector) -> ShadowPrediction: ...


class FeatureBuilder(Protocol):
    def build(self, bars: list[MarketBar]) -> tuple[FeatureVector, ...]: ...


class LiveTrader(Protocol):
    def manage(self, *, expected_epoch: str) -> tuple[DecisionRecord, ...]: ...

    def run(
        self,
        vectors: tuple[FeatureVector, ...],
        *,
        expected_epoch: str,
        universe_id: str | None = None,
    ) -> tuple[DecisionRecord, ...]: ...


class EventRouter(Protocol):
    def run(
        self, vectors: tuple[FeatureVector, ...], *, expected_epoch: str
    ) -> tuple[DecisionRecord, ...]: ...


class LiveFeatureBuilder:
    def __init__(self, feature_schema: str) -> None:
        self._feature_schema = feature_schema

    def build(self, bars: list[MarketBar]) -> tuple[FeatureVector, ...]:
        return build_feature_vectors(bars, feature_schema=self._feature_schema)


class TradingWorker:
    """Runs the always-on inference cycle; execution remains separately gated."""

    def __init__(
        self,
        *,
        store: OperationalStore,
        market_data: MarketData,
        challenger: ChallengerPredictor,
        universe: DailyUniverse,
        feature_builder: FeatureBuilder | None = None,
        live_trader: LiveTrader | None = None,
        event_router: EventRouter | None = None,
        live_started_at: datetime | None = None,
    ) -> None:
        self._store = store
        self._market_data = market_data
        self._challenger = challenger
        self._universe = universe
        self._feature_builder = feature_builder or LiveFeatureBuilder(
            challenger.status.feature_schema or "bar-features-v3"
        )
        self._live_trader = live_trader
        self._event_router = event_router
        self._live_started_at = (
            live_started_at or datetime.now(UTC) if live_trader is not None else None
        )
        self._execution_epoch: str | None = None
        self._bars: dict[tuple[str, datetime], MarketBar] = {}
        self._market_data_bootstrapped = False
        self._universe_id: str | None = None

    def run_cycle(self) -> tuple[DecisionRecord, ...]:
        state = self._store.get_agent_state()
        if not state.is_reconciled:
            raise RuntimeError("worker execution epoch is not reconciled")
        if self._execution_epoch is not None and state.execution_epoch != self._execution_epoch:
            raise RuntimeError("worker lost execution epoch ownership")
        if not self._challenger.status.deployed or not self._challenger.status.loaded:
            raise RuntimeError("challenger is not ready for inference")
        expected_epoch = self._execution_epoch or state.execution_epoch
        if self._live_trader is not None:
            management_records = self._live_trader.manage(expected_epoch=expected_epoch)
            if management_records:
                return management_records
        try:
            universe = self._universe.current(expected_epoch=expected_epoch)
        except UniverseUnavailable:
            return ()
        if universe.universe_id != self._universe_id:
            self._bars.clear()
            self._market_data_bootstrapped = False
            self._universe_id = universe.universe_id
        symbols = tuple(dict.fromkeys(("SPY", *universe.symbols)))
        timeframe = self._challenger.status.timeframe_minutes or 5
        bars = self._market_data.recent_bars(
            symbols,
            timeframe_minutes=timeframe,
            lookback_days=10 if not self._market_data_bootstrapped else 1,
        )
        self._market_data_bootstrapped = True
        self._bars.update({(bar.symbol, bar.timestamp): bar for bar in bars})
        vectors = self._feature_builder.build(list(self._bars.values()))
        if not vectors:
            return ()
        latest_by_symbol: dict[str, datetime] = {}
        for vector in vectors:
            latest_by_symbol[vector.symbol] = max(
                vector.observed_at,
                latest_by_symbol.get(vector.symbol, vector.observed_at),
            )
        latest_vectors = tuple(
            vector for vector in vectors if vector.observed_at == latest_by_symbol[vector.symbol]
        )
        records = []
        for vector in latest_vectors:
            prediction = self._challenger.predict(vector)
            record = self._prediction_record(prediction, universe)
            if self._store.append_decision_once(record, expected_epoch=expected_epoch):
                records.append(record)
        if self._event_router is not None:
            try:
                records.extend(
                    self._event_router.run(latest_vectors, expected_epoch=expected_epoch)
                )
            except Exception:
                logger.exception("shadow event routing failed; live trading remains enabled")
        if self._live_trader is not None:
            eligible_vectors = tuple(
                vector
                for vector in latest_vectors
                if vector.symbol in universe.symbols
                and (self._live_started_at is None or vector.observed_at > self._live_started_at)
            )
            live_vectors = tuple(
                vector
                for vector in eligible_vectors
                if self._store.append_decision_once(
                    self._live_claim_record(vector), expected_epoch=expected_epoch
                )
            )
            if not live_vectors:
                return tuple(records)
            records.extend(
                self._live_trader.run(
                    live_vectors,
                    expected_epoch=expected_epoch,
                    universe_id=universe.universe_id,
                )
            )
        return tuple(records)

    def run_forever(
        self,
        *,
        reconcile: Callable[[], object],
        poll_seconds: int = 15,
        sleep: Callable[[float], None] = time.sleep,
        heartbeat_path: Path = Path("/tmp/worker-heartbeat"),
    ) -> None:
        reconcile()
        state = self._store.get_agent_state()
        if not state.is_reconciled:
            raise RuntimeError("startup reconciliation did not complete")
        self._execution_epoch = state.execution_epoch
        consecutive_failures = 0
        while True:
            try:
                records = self.run_cycle()
                consecutive_failures = 0
                if records:
                    logger.info("persisted %d worker decisions", len(records))
                heartbeat_path.touch()
            except Exception:
                consecutive_failures += 1
                logger.exception("trading worker cycle failed")
                if consecutive_failures >= 5:
                    raise
            sleep(poll_seconds)

    def _prediction_record(
        self, prediction: ShadowPrediction, universe: UniverseSnapshot
    ) -> DecisionRecord:
        authority = self._challenger.status.authority or "SHADOW_ONLY"
        model_label = "paper-live model" if authority == "PAPER_LIVE" else "shadow model"
        decision_id = str(
            uuid5(
                NAMESPACE_URL,
                ":".join(
                    (
                        "challenger-prediction",
                        prediction.run_id,
                        prediction.symbol,
                        prediction.observed_at.isoformat(),
                    )
                ),
            )
        )
        return DecisionRecord.create(
            decision_id=decision_id,
            decision_type="CHALLENGER_PREDICTION",
            occurred_at=prediction.observed_at,
            symbol=prediction.symbol,
            summary=(
                f"{model_label} {prediction.run_id} predicted {prediction.value:.6f} "
                f"({prediction.signal})"
            ),
            payload={
                "authority": authority,
                "run_id": prediction.run_id,
                "value": prediction.value,
                "signal": prediction.signal,
                "universe_id": universe.universe_id,
            },
            public=True,
            public_summary=f"{model_label.title()} signal: {prediction.signal}",
        )

    def _live_claim_record(self, vector: FeatureVector) -> DecisionRecord:
        run_id = self._challenger.status.run_id or "unknown-model"
        return DecisionRecord.create(
            decision_id=str(
                uuid5(
                    NAMESPACE_URL,
                    ":".join(
                        (
                            "live-bar-evaluation",
                            run_id,
                            vector.symbol,
                            vector.observed_at.isoformat(),
                        )
                    ),
                )
            ),
            decision_type="LIVE_BAR_EVALUATION_CLAIM",
            occurred_at=vector.observed_at,
            symbol=vector.symbol,
            summary=f"claimed one live evaluation for {run_id}",
        )

from __future__ import annotations

from datetime import date, datetime
from decimal import Decimal
from typing import Protocol

from pydantic import Field

from catalyst_router.domain import DecisionRecord, FrozenModel

UNIVERSE_POLICY_VERSION = "universe-v1"


class UniverseUnavailable(RuntimeError):
    pass


class UniverseCandidate(FrozenModel):
    symbol: str
    most_active_rank: int | None = Field(default=None, gt=0)
    gainer_rank: int | None = Field(default=None, gt=0)
    loser_rank: int | None = Field(default=None, gt=0)
    price: Decimal = Field(gt=0)
    prior_day_dollar_volume: Decimal = Field(ge=0)
    spread_bps: Decimal = Field(ge=0)
    active: bool
    tradable: bool
    options_enabled: bool


class UniverseSnapshot(FrozenModel):
    universe_id: str
    policy_version: str
    session_date: date
    selected_at: datetime
    symbols: tuple[str, ...]
    source_ranks: dict[str, dict[str, int]]
    rejections: dict[str, tuple[str, ...]]
    candidate_evidence: dict[str, UniverseCandidate] = Field(default_factory=dict)


class UniverseSelector:
    MIN_PRICE = Decimal("5")
    MIN_DOLLAR_VOLUME = Decimal("50000000")
    MAX_SPREAD_BPS = Decimal("15")

    def __init__(self, *, target_size: int = 20) -> None:
        if target_size < 1:
            raise ValueError("universe target size must be positive")
        self._target_size = target_size

    def select(
        self,
        *,
        session_date: date,
        selected_at: datetime,
        candidates: tuple[UniverseCandidate, ...],
    ) -> UniverseSnapshot:
        if selected_at.tzinfo is None:
            raise ValueError("universe selection time must be timezone-aware")
        merged = self._merge(candidates)
        accepted: list[tuple[float, str, UniverseCandidate]] = []
        rejections: dict[str, tuple[str, ...]] = {}
        source_ranks: dict[str, dict[str, int]] = {}
        for symbol, item in sorted(merged.items()):
            reasons = self._rejection_reasons(item)
            if reasons:
                rejections[symbol] = reasons
                continue
            ranks = {
                source: rank
                for source, rank in (
                    ("most_active", item.most_active_rank),
                    ("gainer", item.gainer_rank),
                    ("loser", item.loser_rank),
                )
                if rank is not None
            }
            source_ranks[symbol] = ranks
            score = sum(1 / (60 + rank) for rank in ranks.values())
            accepted.append((score, symbol, item))
        accepted.sort(key=lambda value: (-value[0], value[1]))
        symbols = tuple(symbol for _, symbol, _ in accepted[: self._target_size])
        selected_ranks = {symbol: source_ranks[symbol] for symbol in symbols}
        return UniverseSnapshot(
            universe_id=f"{UNIVERSE_POLICY_VERSION}:{session_date.isoformat()}",
            REDACTED,
            session_date=session_date,
            selected_at=selected_at,
            symbols=symbols,
            source_ranks=selected_ranks,
            rejections=rejections,
            candidate_evidence=merged,
        )

    @staticmethod
    def _merge(candidates: tuple[UniverseCandidate, ...]) -> dict[str, UniverseCandidate]:
        merged: dict[str, UniverseCandidate] = {}
        for item in candidates:
            symbol = item.symbol.upper()
            current = merged.get(symbol)
            if current is None:
                merged[symbol] = item.model_copy(update={"symbol": symbol})
                continue
            merged[symbol] = current.model_copy(
                update={
                    "most_active_rank": _minimum_rank(
                        current.most_active_rank, item.most_active_rank
                    ),
                    "gainer_rank": _minimum_rank(current.gainer_rank, item.gainer_rank),
                    "loser_rank": _minimum_rank(current.loser_rank, item.loser_rank),
                }
            )
        return merged

    def _rejection_reasons(self, item: UniverseCandidate) -> tuple[str, ...]:
        reasons = []
        if not item.active:
            reasons.append("asset is not active")
        if not item.tradable:
            reasons.append("asset is not tradable")
        if not item.options_enabled:
            reasons.append("options are not enabled")
        if item.price < self.MIN_PRICE:
            reasons.append("price below $5")
        if item.prior_day_dollar_volume < self.MIN_DOLLAR_VOLUME:
            reasons.append("prior-day dollar volume below $50M")
        if item.spread_bps > self.MAX_SPREAD_BPS:
            reasons.append("underlying spread exceeds 15 bps")
        return tuple(reasons)


class UniverseSource(Protocol):
    def session_date(self) -> date: ...

    def build(self, session_date: date) -> UniverseSnapshot: ...


class UniverseStore(Protocol):
    def get_daily_universe(self, session_date: date) -> UniverseSnapshot | None: ...

    def put_daily_universe(self, snapshot: UniverseSnapshot, *, expected_epoch: str) -> bool: ...

    def append_decision_once(
        self, record: DecisionRecord, *, expected_epoch: str | None = None
    ) -> bool: ...


class DailyUniverse:
    """Returns one immutable point-in-time universe for each Alpaca session."""

    def __init__(self, *, store: UniverseStore, source: UniverseSource) -> None:
        self._store = store
        self._source = source

    def current(self, *, expected_epoch: str) -> UniverseSnapshot:
        session_date = self._source.session_date()
        existing = self._store.get_daily_universe(session_date)
        if existing is not None:
            return existing
        proposed = self._source.build(session_date)
        if self._store.put_daily_universe(proposed, expected_epoch=expected_epoch):
            self._store.append_decision_once(
                DecisionRecord.create(
                    decision_id=proposed.universe_id,
                    decision_type="UNIVERSE_SELECTED",
                    occurred_at=proposed.selected_at,
                    summary=(
                        f"selected {len(proposed.symbols)} option-enabled underlyings "
                        f"for {proposed.session_date}"
                    ),
                    payload=proposed.model_dump(mode="json"),
                    public=True,
                    public_summary=f"Selected {len(proposed.symbols)} liquid underlyings",
                ),
                expected_epoch=expected_epoch,
            )
            return proposed
        winner = self._store.get_daily_universe(proposed.session_date)
        if winner is None:
            raise RuntimeError("daily universe was claimed but could not be loaded")
        return winner


def _minimum_rank(left: int | None, right: int | None) -> int | None:
    if left is None:
        return right
    if right is None:
        return left
    return min(left, right)

from decimal import ROUND_FLOOR, Decimal

from catalyst_router.domain import (
    AgentMode,
    AgentState,
    InstrumentType,
    PortfolioRiskState,
    RiskDecision,
    RiskDecisionStatus,
    Route,
    Side,
    TradeIntent,
)


class RiskGovernor:
    MAX_POSITIONS = 6
    MAX_TRADE_RISK_RATE = Decimal("0.01")
    REDUCED_TRADE_RISK_RATE = Decimal("0.005")
    MAX_TOTAL_RISK_RATE = Decimal("0.04")
    MAX_OVERNIGHT_RISK_RATE = Decimal("0.02")
    MAX_GROUP_RISK_RATE = Decimal("0.02")
    DE_RISK_DAILY_LOSS_RATE = Decimal("0.02")
    MAX_DAILY_LOSS_RATE = Decimal("0.04")
    MAX_COMPETITION_DRAWDOWN_RATE = Decimal("0.12")
    MAX_QUOTE_AGE_SECONDS = Decimal("5")

    def __init__(self, *, options_execution_enabled: bool = False) -> None:
        self._options_execution_enabled = options_execution_enabled

    def evaluate(
        self,
        intent: TradeIntent,
        agent: AgentState,
        portfolio: PortfolioRiskState,
        *,
        market_is_open: bool,
        overnight: bool = False,
        trading_blocked: bool = False,
        options_trading_level: int = 0,
        options_buying_power: Decimal | None = None,
    ) -> RiskDecision:
        vetoes: list[str] = []
        if intent.route is Route.NO_TRADE:
            vetoes.append("NO_TRADE cannot create exposure")
        if intent.instrument_type is InstrumentType.OPTION and intent.side is not Side.BUY:
            vetoes.append("short option legs are prohibited")
        if intent.instrument_type is InstrumentType.OPTION and not self._options_execution_enabled:
            vetoes.append("live option execution is not enabled")
        if intent.instrument_type is InstrumentType.OPTION and options_trading_level < 2:
            vetoes.append("options trading level 2 is required")
        if intent.route is Route.LIQUIDITY_REVERSION and (
            intent.instrument_type is not InstrumentType.EQUITY
        ):
            vetoes.append("liquidity reversion must use equities")
        if intent.route is Route.REGIME_TREND and (
            intent.instrument_type is not InstrumentType.EQUITY
        ):
            vetoes.append("regime trend must use equities")
        if trading_blocked:
            vetoes.append("Alpaca account is blocked from trading")
        if agent.mode is not AgentMode.RUNNING:
            vetoes.append(f"agent mode is {agent.mode}")
        if not agent.is_reconciled:
            vetoes.append("startup reconciliation is incomplete")
        if not market_is_open:
            vetoes.append("market is closed")
        if not intent.data_quality_passed:
            vetoes.append("intent data failed quality gates")
        if intent.quote_age_seconds > self.MAX_QUOTE_AGE_SECONDS:
            vetoes.append("quote is stale")
        if intent.stop_distance <= 0:
            vetoes.append("stop distance must be positive")
        if intent.side is Side.BUY and intent.stop_price >= intent.entry_price:
            vetoes.append("buy stop must be below entry")
        if intent.side is Side.SELL and intent.stop_price <= intent.entry_price:
            vetoes.append("sell stop must be above entry")
        if portfolio.position_count >= self.MAX_POSITIONS:
            vetoes.append("maximum position count reached")

        daily_loss = max(Decimal("0"), -portfolio.daily_pnl)
        if daily_loss >= portfolio.equity * self.MAX_DAILY_LOSS_RATE:
            vetoes.append("daily loss circuit breaker reached")
        if portfolio.competition_drawdown >= self.MAX_COMPETITION_DRAWDOWN_RATE:
            vetoes.append("competition drawdown kill threshold reached")

        if vetoes:
            return self._veto(intent, vetoes)

        risk_rate = (
            self.REDUCED_TRADE_RISK_RATE
            if daily_loss >= portfolio.equity * self.DE_RISK_DAILY_LOSS_RATE
            else self.MAX_TRADE_RISK_RATE
        )
        allowed_risk = portfolio.equity * risk_rate
        total_capacity = portfolio.equity * self.MAX_TOTAL_RISK_RATE - portfolio.total_open_risk
        group_capacity = (
            portfolio.equity * self.MAX_GROUP_RISK_RATE
            - portfolio.group_open_risk.get(intent.exposure_group, Decimal("0"))
        )
        capacities = [allowed_risk, total_capacity, group_capacity]
        if overnight:
            capacities.append(
                portfolio.equity * self.MAX_OVERNIGHT_RISK_RATE - portfolio.overnight_open_risk
            )
        risk_amount = max(Decimal("0"), min(capacities))
        buying_power = (
            options_buying_power
            if intent.instrument_type is InstrumentType.OPTION
            else portfolio.buying_power
        )
        if buying_power is None:
            return self._veto(intent, ["options buying power is unavailable"])
        affordable = (buying_power / intent.entry_cost_per_unit).to_integral_value(
            rounding=ROUND_FLOOR
        )
        by_stop = (risk_amount / intent.stop_risk_per_unit).to_integral_value(rounding=ROUND_FLOOR)
        quantity = int(min(affordable, by_stop))
        if quantity < 1:
            return self._veto(intent, ["risk or buying-power capacity is insufficient"])

        actual_risk = intent.stop_risk_per_unit * quantity
        status = (
            RiskDecisionStatus.REDUCED
            if risk_amount < allowed_risk or risk_rate < self.MAX_TRADE_RISK_RATE
            else RiskDecisionStatus.APPROVED
        )
        return RiskDecision(
            status=status,
            intent_id=intent.intent_id,
            quantity=quantity,
            risk_amount=actual_risk,
            checks=(
                "agent running and reconciled",
                "data and market gates passed",
                "trade, portfolio, group, and buying-power limits passed",
            ),
        )

    @staticmethod
    def _veto(intent: TradeIntent, vetoes: list[str]) -> RiskDecision:
        return RiskDecision(
            status=RiskDecisionStatus.VETOED,
            intent_id=intent.intent_id,
            quantity=0,
            risk_amount=Decimal("0"),
            checks=tuple(vetoes),
        )

class LiveTradingCycle:
    """Evaluates the incumbent and submits at most one protected equity entry per cycle."""

    MAX_ENTRY_NOTIONAL_RATE = Decimal("0.10")
    MAX_CONCURRENT_POSITIONS = RiskGovernor.MAX_POSITIONS
    MANAGED_OPTION_QUOTE_GRACE = timedelta(seconds=60)

    def __init__(
        self,
        *,
        store: OperationalStore,
        broker: PaperBroker,
        quotes: QuoteSource,
        strategy: EntryStrategy | None = None,
        risk_governor: RiskGovernor | None = None,
        option_quotes: QuoteSource | None = None,
    ) -> None:
        self._store = store
        self._broker = broker
        self._quotes = quotes
        self._strategy = strategy or IncumbentStrategy()
        self._risk = risk_governor or RiskGovernor()
        self._option_quotes = option_quotes
        self._option_quote_failures: dict[str, datetime] = {}
        self._gateway = ExecutionGateway(store=store, broker=broker)

    def run(
        self,
        vectors: tuple[FeatureVector, ...],
        *,
        expected_epoch: str,
        universe_id: str | None = None,
    ) -> tuple[DecisionRecord, ...]:
        agent = self._store.get_agent_state()
        if agent.mode is not AgentMode.RUNNING:
            return ()
        if agent.execution_epoch != expected_epoch or not agent.is_reconciled:
            raise RuntimeError("worker lost execution epoch ownership")

        snapshot = self._broker.reconciliation_snapshot()
        agent = self._store.update_equity_peak(snapshot.account.equity)
        until_close = snapshot.clock.next_close - snapshot.clock.timestamp
        agent, tracked = self._release_terminal_orders(agent, snapshot)

        close_flatten_due = bool(
            snapshot.positions or snapshot.open_orders
        ) and until_close <= timedelta(minutes=10)
        if close_flatten_due:
            self._broker.flatten()
            return ()
        expired = tuple(
            execution
            for execution in tracked.values()
            if execution.plan.instrument_type is not InstrumentType.OPTION
            and snapshot.clock.timestamp >= execution.plan.expires_at
        )
        if expired:
            for execution in expired:
                self._broker.close_position(execution.plan.symbol)
            return ()

        option_exits = self._manage_option_exits(snapshot, tracked, expected_epoch)
        if option_exits or self._option_quote_failures:
            return option_exits

        last_equity = snapshot.account.last_equity or snapshot.account.equity
        equity_peak = agent.equity_peak or max(last_equity, snapshot.account.equity)
        group_open_risk = self._group_open_risk(tracked)
        portfolio = PortfolioRiskState(
            equity=snapshot.account.equity,
            buying_power=min(
                snapshot.account.buying_power,
                snapshot.account.equity * self.MAX_ENTRY_NOTIONAL_RATE,
            ),
            position_count=max(len(snapshot.positions), len(tracked)),
            total_open_risk=sum(group_open_risk.values(), Decimal("0")),
            overnight_open_risk=Decimal("0"),
            group_open_risk=group_open_risk,
            daily_pnl=snapshot.account.equity - last_equity,
            competition_drawdown=max(
                Decimal("0"),
                (equity_peak - snapshot.account.equity) / equity_peak,
            ),
        )
        publish_public_portfolio(
            self._store,
            build_public_portfolio_point(snapshot, agent, tracked.values()),
            expected_epoch=expected_epoch,
        )
        daily_loss = max(Decimal("0"), -portfolio.daily_pnl)
        if portfolio.competition_drawdown >= RiskGovernor.MAX_COMPETITION_DRAWDOWN_RATE:
            self._halt_and_flatten(AgentMode.KILLED, "competition drawdown kill threshold reached")
            return ()
        if daily_loss >= portfolio.equity * RiskGovernor.MAX_DAILY_LOSS_RATE:
            self._halt_and_flatten(AgentMode.RISK_HALTED, "daily loss circuit breaker reached")
            return ()
        if not self._every_position_is_protected(snapshot, tracked):
            self._halt_and_flatten(
                AgentMode.RISK_HALTED,
                "broker position is missing protective bracket exits",
            )
            return ()
        if (
            not snapshot.clock.is_open
            or snapshot.account.trading_blocked
            or until_close <= timedelta(minutes=15)
            or len(agent.active_order_ids) >= self.MAX_CONCURRENT_POSITIONS
        ):
            return ()
        committed = {execution.plan.symbol for execution in tracked.values()}
        committed_underlyings = {
            execution.plan.underlying_symbol or execution.plan.symbol
            for execution in tracked.values()
        }
        committed.update(position.symbol for position in snapshot.positions)
        committed.update(order.symbol for order in snapshot.open_orders)
        candidates = [
            (signal, vector)
            for vector in vectors
            if vector.symbol not in committed
            and vector.symbol not in committed_underlyings
            and (signal := self._strategy.signal(vector)) is not None
        ]
        for signal, vector in sorted(
            candidates, key=lambda item: (-item[0].confidence, item[1].symbol)
        ):
            quote = self._quotes.latest_quote(vector.symbol)
            intent = self._strategy.create_intent(vector, quote, signal=signal)
            if intent is None:
                continue
            if universe_id is not None:
                intent = intent.model_copy(update={"universe_id": universe_id})
            risk = self._risk.evaluate(
                intent,
                agent,
                portfolio,
                market_is_open=snapshot.clock.is_open,
                trading_blocked=snapshot.account.trading_blocked,
                options_trading_level=snapshot.account.options_trading_level,
                options_buying_power=(
                    min(
                        snapshot.account.options_buying_power,
                        snapshot.account.equity * self.MAX_ENTRY_NOTIONAL_RATE,
                    )
                    if snapshot.account.options_buying_power is not None
                    else None
                ),
            )
            if risk.status is RiskDecisionStatus.VETOED:
                return self._persist_risk_veto(intent, risk, expected_epoch)
            approvals = self._persist_risk_approval(intent, risk, portfolio, expected_epoch)
            execution = self._gateway.execute(
                intent,
                risk,
                expected_epoch=expected_epoch,
                max_active_orders=self.MAX_CONCURRENT_POSITIONS,
            )
            return approvals + self._persist_execution(intent, risk, execution, expected_epoch)
        return ()

    def manage(self, *, expected_epoch: str) -> tuple[DecisionRecord, ...]:
        return self.run((), expected_epoch=expected_epoch)

    @staticmethod
    def _group_open_risk(tracked: dict[str, OrderExecution]) -> dict[str, Decimal]:
        group_open_risk: dict[str, Decimal] = {}
        for execution in tracked.values():
            plan = execution.plan
            group_open_risk[plan.exposure_group] = (
                group_open_risk.get(plan.exposure_group, Decimal("0")) + plan.risk_amount
            )
        return group_open_risk

    def _every_position_is_protected(
        self, snapshot: ReconciliationSnapshot, tracked: dict[str, OrderExecution]
    ) -> bool:
        protected: set[str] = set()
        positions = {position.symbol: position for position in snapshot.positions}
        for client_order_id, execution in tracked.items():
            if execution.plan.instrument_type is InstrumentType.OPTION:
                position = positions.get(execution.plan.symbol)
                expiration = execution.plan.option_expiration_date
                if (
                    position is not None
                    and position.quantity > 0
                    and expiration is not None
                    and expiration > snapshot.clock.timestamp.date()
                ):
                    protected.add(execution.plan.symbol)
                continue
            broker_order = self._broker.get_order_by_client_id(client_order_id)
            if (
                broker_order is not None
                and broker_order.has_active_take_profit
                and broker_order.has_active_stop_loss
            ):
                protected.add(execution.plan.symbol)
        return all(position.symbol in protected for position in snapshot.positions)

    def _manage_option_exits(
        self,
        snapshot: ReconciliationSnapshot,
        tracked: dict[str, OrderExecution],
        expected_epoch: str,
    ) -> tuple[DecisionRecord, ...]:
        positions = {position.symbol: position for position in snapshot.positions}
        managed_symbols = {
            execution.plan.symbol
            for execution in tracked.values()
            if execution.plan.instrument_type is InstrumentType.OPTION
            and execution.plan.symbol in positions
        }
        self._option_quote_failures = {
            symbol: failed_at
            for symbol, failed_at in self._option_quote_failures.items()
            if symbol in managed_symbols
        }
        for client_order_id, execution in tracked.items():
            plan = execution.plan
            position = positions.get(plan.symbol)
            if plan.instrument_type is not InstrumentType.OPTION or position is None:
                continue
            if self._option_quotes is None:
                raise RuntimeError("option position supervision is not configured")
            reason = None
            quote: QuoteSnapshot | None = None
            if snapshot.clock.timestamp >= plan.expires_at:
                reason = "model horizon elapsed"
            else:
                try:
                    quote = self._option_quotes.latest_quote(plan.symbol)
                except Exception:
                    if self._record_option_quote_failure(
                        execution,
                        snapshot.clock.timestamp,
                        f"option quote unavailable for managed position {plan.symbol}",
                    ):
                        return ()
                    continue
                quote_age = snapshot.clock.timestamp - quote.timestamp
                if quote.feed != "indicative" or not (
                    -ModelStrategy.MAX_CLOCK_SKEW <= quote_age <= timedelta(seconds=5)
                ):
                    if self._record_option_quote_failure(
                        execution,
                        snapshot.clock.timestamp,
                        f"option quote failed quality gates for managed position {plan.symbol}",
                    ):
                        return ()
                    continue
                failed_at = (
                    execution.option_quote_failure_started_at
                    or self._option_quote_failures.pop(plan.symbol, None)
                )
                if failed_at is not None:
                    self._option_quote_failures.pop(plan.symbol, None)
                    recovered = execution.model_copy(
                        update={
                            "option_quote_failure_started_at": None,
                            "version": execution.version + 1,
                            "updated_at": datetime.now(UTC),
                        }
                    )
                    self._store.update_order(recovered, expected_status=execution.status)
                    logger.info(
                        "managed option quote recovered for %s after %.1f seconds",
                        plan.symbol,
                        (snapshot.clock.timestamp - failed_at).total_seconds(),
                    )
                if quote.bid_price <= plan.stop_price:
                    reason = "premium stop reached"
                elif quote.bid_price >= plan.take_profit_price:
                    reason = "premium target reached"
            if reason is None:
                continue
            exit_client_order_id = (
                "crx-" + uuid5(NAMESPACE_URL, f"option-exit-v1:{plan.client_order_id}").hex
            )
            broker_exit = self._broker.get_order_by_client_id(exit_client_order_id)
            if broker_exit is not None and self._is_terminal_rejection(broker_exit.status):
                self._halt_and_flatten(
                    AgentMode.RISK_HALTED,
                    f"option exit {exit_client_order_id} was rejected or canceled",
                )
                return ()
            if broker_exit is None:
                try:
                    broker_exit = self._broker.submit_option_exit(
                        plan.symbol,
                        int(position.quantity),
                        exit_client_order_id,
                    )
                except Exception:
                    self._halt_and_flatten(
                        AgentMode.RISK_HALTED,
                        f"option exit {exit_client_order_id} submission failed",
                    )
                    return ()
                if self._is_terminal_rejection(broker_exit.status):
                    self._halt_and_flatten(
                        AgentMode.RISK_HALTED,
                        f"option exit {exit_client_order_id} was rejected",
                    )
                    return ()
            record = DecisionRecord.create(
                decision_id=str(uuid5(NAMESPACE_URL, f"option-exit:{client_order_id}:{reason}")),
                decision_type="OPTION_EXIT",
                route=Route.MODEL_DIRECTIONAL,
                symbol=plan.underlying_symbol or plan.symbol,
                summary=f"closed {plan.symbol}: {reason}",
                payload={
                    "contract_symbol": plan.symbol,
                    "reason": reason,
                    "bid_price": str(quote.bid_price) if quote is not None else None,
                    "exit_client_order_id": exit_client_order_id,
                    "broker_status": broker_exit.status,
                    "universe_id": plan.universe_id,
                },
                public=True,
                public_summary=f"Closed option position: {reason}",
            )
            return (
                (record,)
                if self._store.append_decision_once(record, expected_epoch=expected_epoch)
                else ()
            )
        return ()

    def _record_option_quote_failure(
        self, execution: OrderExecution, observed_at: datetime, reason: str
    ) -> bool:
        symbol = execution.plan.symbol
        failed_at = execution.option_quote_failure_started_at
        if failed_at is None:
            failed_at = observed_at
            degraded = execution.model_copy(
                update={
                    "option_quote_failure_started_at": failed_at,
                    "version": execution.version + 1,
                    "updated_at": datetime.now(UTC),
                }
            )
            self._store.update_order(degraded, expected_status=execution.status)
        self._option_quote_failures[symbol] = failed_at
        failure_age = observed_at - failed_at
        if failure_age < self.MANAGED_OPTION_QUOTE_GRACE:
            logger.warning(
                "%s; pausing new entries during %.1f/%.1f second grace period",
                reason,
                failure_age.total_seconds(),
                self.MANAGED_OPTION_QUOTE_GRACE.total_seconds(),
            )
            return False
        self._halt_and_flatten(AgentMode.RISK_HALTED, reason)
        return True

    @staticmethod
    def _is_terminal_rejection(status: str) -> bool:
        return status.rsplit(".", 1)[-1].lower() in {
            "canceled",
            "expired",
            "rejected",
            "replaced",
        }

    def _release_terminal_orders(
        self, agent: AgentState, snapshot: ReconciliationSnapshot
    ) -> tuple[AgentState, dict[str, OrderExecution]]:
        tracked: dict[str, OrderExecution] = {}
        released = False
        for client_order_id in agent.active_order_ids:
            execution = self._store.get_order(client_order_id)
            if execution is None:
                raise RuntimeError("active order has no durable execution record")
            if self._release_terminal_order(client_order_id, snapshot, execution):
                released = True
                continue
            tracked[client_order_id] = execution
        return (self._store.get_agent_state() if released else agent), tracked

    def _release_terminal_order(
        self,
        client_order_id: str,
        snapshot: ReconciliationSnapshot,
        execution: OrderExecution,
    ) -> bool:
        broker_order = self._broker.get_order_by_client_id(client_order_id)
        status = (
            broker_order.status.rsplit(".", 1)[-1].lower()
            if broker_order is not None
            else "missing"
        )
        terminal = status in {"canceled", "expired", "filled", "rejected", "replaced"}
        expired_and_missing = (
            status == "missing" and snapshot.clock.timestamp >= execution.plan.expires_at
        )
        symbol = execution.plan.symbol
        symbol_is_flat = not any(
            position.symbol == symbol for position in snapshot.positions
        ) and not any(order.symbol == symbol for order in snapshot.open_orders)
        if (terminal or expired_and_missing) and symbol_is_flat:
            self._store.clear_active_order(client_order_id)
            return True
        return False

    def _halt_and_flatten(self, mode: AgentMode, reason: str) -> None:
        self._store.transition_agent_mode(
            mode,
            reason=reason,
            record=DecisionRecord.create(
                decision_type="CIRCUIT_BREAKER",
                summary=reason,
                payload={"mode": mode, "reason": reason},
            ),
        )
        self._broker.flatten()

    def _persist_risk_veto(
        self, intent: TradeIntent, risk: RiskDecision, expected_epoch: str
    ) -> tuple[DecisionRecord, ...]:
        record = DecisionRecord.create(
            decision_id=str(uuid5(NAMESPACE_URL, f"risk-veto:{intent.intent_id}")),
            decision_type="RISK_VETO",
            route=intent.route,
            symbol=intent.underlying_symbol or intent.symbol,
            summary="; ".join(risk.checks),
            payload={
                "intent_id": intent.intent_id,
                "contract_symbol": intent.symbol,
                "universe_id": intent.universe_id,
                "checks": risk.checks,
            },
            public=True,
            public_summary=f"Risk governor vetoed {intent.symbol}",
        )
        return (
            (record,)
            if self._store.append_decision_once(record, expected_epoch=expected_epoch)
            else ()
        )

    def _persist_risk_approval(
        self,
        intent: TradeIntent,
        risk: RiskDecision,
        portfolio: PortfolioRiskState,
        expected_epoch: str,
    ) -> tuple[DecisionRecord, ...]:

from __future__ import annotations

from decimal import Decimal
from typing import cast

from alpaca.common.exceptions import APIError
from alpaca.trading.client import TradingClient
from alpaca.trading.enums import (
    OrderClass,
    OrderSide,
    PositionIntent,
    QueryOrderStatus,
    TimeInForce,
)
from alpaca.trading.models import Clock, Order, Position, TradeAccount
from alpaca.trading.requests import (
    GetOrdersRequest,
    LimitOrderRequest,
    MarketOrderRequest,
    StopLossRequest,
    TakeProfitRequest,
)

from catalyst_router.domain import (
    AccountSnapshot,
    BrokerOrderSnapshot,
    InstrumentType,
    MarketClockSnapshot,
    OpenOrderSnapshot,
    OrderPlan,
    PositionSnapshot,
    ReconciliationSnapshot,
    Side,
)

ALPACA_PAPER_BASE_URL = "https://paper-api.alpaca.markets"
ALPACA_PAPER_API_ROOT = f"{ALPACA_PAPER_BASE_URL}/v2"
# Alpaca reports a filled bracket's exits as an OCO pair: the working leg is
# "new" while its resting sibling is "held". A held leg is live server-side
# protection, so excluding it would read every protected position as unprotected.
_ACTIVE_PROTECTIVE_STATUSES = {
    "accepted",
    "held",
    "new",
    "partially_filled",
    "pending_new",
}


class AlpacaPaperBroker:
    """Alpaca adapter hard-pinned to the paper-trading endpoint."""

    def __init__(self, key: str, secret: str) -> None:
        self._client = TradingClient(
            key,
            secret,
            paper=True,
            url_override=ALPACA_PAPER_BASE_URL,
        )

    def reconciliation_snapshot(self) -> ReconciliationSnapshot:
        account = cast(TradeAccount, self._client.get_account())
        clock = cast(Clock, self._client.get_clock())
        positions = cast(list[Position], self._client.get_all_positions())
        orders = cast(
            list[Order],
            self._client.get_orders(
                filter=GetOrdersRequest(status=QueryOrderStatus.OPEN, limit=500)
            ),
        )
        return ReconciliationSnapshot(
            account=AccountSnapshot(
                equity=Decimal(str(account.equity)),
                buying_power=Decimal(str(account.buying_power)),
                cash=Decimal(str(account.cash)),
                portfolio_value=Decimal(str(account.portfolio_value)),
                trading_blocked=bool(account.trading_blocked),
                options_trading_level=int(account.options_trading_level or 0),
                options_buying_power=(
                    Decimal(str(account.options_buying_power))
                    if account.options_buying_power is not None
                    else None
                ),
                last_equity=(
                    Decimal(str(account.last_equity)) if account.last_equity is not None else None
                ),
            ),
            clock=MarketClockSnapshot(
                is_open=bool(clock.is_open),
                timestamp=clock.timestamp,
                next_open=clock.next_open,
                next_close=clock.next_close,
            ),
            positions=tuple(
                PositionSnapshot(
                    symbol=position.symbol,
                    asset_class=str(position.asset_class),
                    quantity=Decimal(str(position.qty)),
                    market_value=Decimal(str(position.market_value or 0)),
                    unrealized_pl=Decimal(str(position.unrealized_pl or 0)),
                )
                for position in positions
            ),
            open_orders=tuple(
                OpenOrderSnapshot(
                    client_order_id=order.client_order_id,
                    symbol=order.symbol or "",
                    status=str(order.status),
                    side=str(order.side or ""),
                    quantity=Decimal(str(order.qty)) if order.qty is not None else None,
                )
                for order in orders
            ),
        )

    def get_order_by_client_id(self, client_order_id: str) -> BrokerOrderSnapshot | None:
        try:
            order = cast(Order, self._client.get_order_by_client_id(client_order_id))
        except APIError as exc:
            if exc.status_code == 404:
                return None
            raise
        return self._order_snapshot(order)

    def submit_order(self, plan: OrderPlan) -> BrokerOrderSnapshot:
        if plan.instrument_type is InstrumentType.OPTION:
            if plan.side is not Side.BUY:
                raise ValueError("option opening orders must buy to open")
            request = LimitOrderRequest(
                symbol=plan.symbol,
                qty=plan.quantity,
                side=OrderSide.BUY,
                time_in_force=TimeInForce.DAY,
                extended_hours=False,
                client_order_id=plan.client_order_id,
                limit_price=float(plan.limit_price),
                position_intent=PositionIntent.BUY_TO_OPEN,
            )
        else:
            request = LimitOrderRequest(
                symbol=plan.symbol,
                qty=plan.quantity,
                side=OrderSide.BUY if plan.side is Side.BUY else OrderSide.SELL,
                time_in_force=TimeInForce.DAY,
                order_class=OrderClass.BRACKET,
                extended_hours=False,
                client_order_id=plan.client_order_id,
                limit_price=float(plan.limit_price),
                take_profit=TakeProfitRequest(limit_price=float(plan.take_profit_price)),
                stop_loss=StopLossRequest(stop_price=float(plan.stop_price)),
            )
        order = cast(
            Order,
            self._client.submit_order(request),
        )
        return self._order_snapshot(order)

    def close_position(self, symbol: str) -> None:
        """Cancels the symbol's resting bracket legs, then closes just that position."""
        orders = cast(
            list[Order],
            self._client.get_orders(
                filter=GetOrdersRequest(status=QueryOrderStatus.OPEN, symbols=[symbol], limit=500)
            ),
        )
        for order in orders:
            try:
                self._client.cancel_order_by_id(str(order.id))
            except APIError as exc:
                if exc.status_code not in {404, 422}:
                    raise
        try:
            self._client.close_position(symbol)
        except APIError as exc:
            if exc.status_code != 404:
                raise

    def submit_option_exit(
        self, symbol: str, quantity: int, client_order_id: str
    ) -> BrokerOrderSnapshot:
        order = cast(
            Order,
            self._client.submit_order(
                MarketOrderRequest(
                    symbol=symbol,
                    qty=quantity,
                    side=OrderSide.SELL,
                    time_in_force=TimeInForce.DAY,
                    extended_hours=False,
                    client_order_id=client_order_id,
                    position_intent=PositionIntent.SELL_TO_CLOSE,
                )
            ),
        )
        return self._order_snapshot(order)

    def flatten(self) -> None:
        self._client.close_all_positions(cancel_orders=True)

    @staticmethod
    def _order_snapshot(order: Order) -> BrokerOrderSnapshot:
        if order.symbol is None or order.side is None or order.qty is None:
            raise RuntimeError("Alpaca order response is incomplete")
        active_legs = [
            leg
            for leg in getattr(order, "legs", None) or []
            if str(leg.status).rsplit(".", 1)[-1].lower() in _ACTIVE_PROTECTIVE_STATUSES
        ]
        return BrokerOrderSnapshot(
            order_id=str(order.id),
            client_order_id=order.client_order_id,
            symbol=order.symbol,
            side=Side.BUY if order.side == OrderSide.BUY else Side.SELL,
            quantity=int(Decimal(str(order.qty))),
            status=str(order.status),
            has_active_take_profit=any(
                str(leg.type).rsplit(".", 1)[-1].lower() == "limit" for leg in active_legs
            ),
            has_active_stop_loss=any(
                str(leg.type).rsplit(".", 1)[-1].lower() in {"stop", "stop_limit"}
                for leg in active_legs
            ),
        )

