class ExecutionGateway:
    def __init__(self, *, store: OperationalStore, broker: PaperBroker) -> None:
        self._store = store
        self._broker = broker

    def execute(
        self,
        intent: TradeIntent,
        risk: RiskDecision,
        *,
        expected_epoch: str,
        max_active_orders: int,
    ) -> OrderExecution:
        if risk.intent_id != intent.intent_id or risk.status is RiskDecisionStatus.VETOED:
            raise ValueError("an approved risk decision matching the intent is required")
        plan = self._plan(intent, risk)
        prepared = OrderExecution(plan=plan, request_hash=self._request_hash(plan))
        claimed = self._store.claim_order(
            prepared, expected_epoch=expected_epoch, max_active_orders=max_active_orders
        )
        execution = prepared if claimed else self._store.get_order(plan.client_order_id)
        if execution is None:
            raise RuntimeError("claimed order execution could not be loaded")
        if execution.request_hash != prepared.request_hash:
            raise RuntimeError("client order id was reused with a different request")
        if execution.status in {
            OrderExecutionStatus.ACKNOWLEDGED,
            OrderExecutionStatus.REJECTED,
        }:
            return execution

        broker_order = self._broker.get_order_by_client_id(plan.client_order_id)
        if broker_order is not None:
            return self._acknowledge(execution, broker_order)
        try:
            broker_order = self._broker.submit_order(plan)
        except Exception:
            broker_order = self._broker.get_order_by_client_id(plan.client_order_id)
            if broker_order is not None:
                return self._acknowledge(execution, broker_order)
            return self._transition(execution, OrderExecutionStatus.UNKNOWN)
        return self._acknowledge(execution, broker_order)

    @staticmethod
    def _plan(intent: TradeIntent, risk: RiskDecision) -> OrderPlan:
        client_order_id = "cr-" + uuid5(NAMESPACE_URL, f"paper-order-v1:{intent.intent_id}").hex
        take_profit = intent.take_profit_price or (
            (intent.entry_price * Decimal("1.04")).quantize(_CENT, rounding=ROUND_CEILING)
            if intent.side is Side.BUY
            else (intent.entry_price * Decimal("0.96")).quantize(_CENT, rounding=ROUND_FLOOR)
        )
        created_at = datetime.now(UTC)
        return OrderPlan(
            client_order_id=client_order_id,
            intent_id=intent.intent_id,
            symbol=intent.symbol,
            side=intent.side,
            quantity=risk.quantity,
            limit_price=intent.entry_price,
            stop_price=intent.stop_price,
            take_profit_price=take_profit,
            risk_amount=risk.risk_amount,
            exposure_group=intent.exposure_group,
            instrument_type=intent.instrument_type,
            underlying_symbol=intent.underlying_symbol,
            option_type=intent.option_type,
            option_expiration_date=intent.option_expiration_date,
            universe_id=intent.universe_id,
            created_at=created_at,
            expires_at=created_at + timedelta(minutes=intent.expected_horizon_minutes),
        )

    @staticmethod
    def _request_hash(plan: OrderPlan) -> str:
        if plan.instrument_type is InstrumentType.OPTION:
            request = {
                "client_order_id": plan.client_order_id,
                "limit_price": str(plan.limit_price),
                "position_intent": "buy_to_open",
                "quantity": plan.quantity,
                "side": plan.side,
                "symbol": plan.symbol,
                "time_in_force": "day",
                "type": "limit",
            }
        else:
            request = {
                "client_order_id": plan.client_order_id,
                "limit_price": str(plan.limit_price),
                "quantity": plan.quantity,
                "side": plan.side,
                "stop_price": str(plan.stop_price),
                "symbol": plan.symbol,
                "take_profit_price": str(plan.take_profit_price),
                "time_in_force": "day",
                "type": "limit",
            }
        encoded = json.dumps(request, sort_keys=True, separators=(",", ":")).encode()
        return hashlib.sha256(encoded).hexdigest()

    def _acknowledge(
        self, execution: OrderExecution, broker_order: BrokerOrderSnapshot
    ) -> OrderExecution:
        plan = execution.plan
        if (
            broker_order.client_order_id != plan.client_order_id
            or broker_order.symbol != plan.symbol
            or broker_order.side is not plan.side
            or broker_order.quantity != plan.quantity
        ):
            raise RuntimeError("Alpaca order does not match the durable order plan")
        status = broker_order.status.rsplit(".", 1)[-1].lower()
        target = (
            OrderExecutionStatus.REJECTED
            if status in {"canceled", "expired", "rejected", "replaced"}
            else OrderExecutionStatus.ACKNOWLEDGED
        )
        updated = self._transition(
            execution,
            target,
            alpaca_order_id=broker_order.order_id,
            broker_status=broker_order.status,
        )
        if target is OrderExecutionStatus.REJECTED:
            self._store.clear_active_order(plan.client_order_id)
        return updated

    def _transition(
        self,
        execution: OrderExecution,
        status: OrderExecutionStatus,
        *,
        alpaca_order_id: str | None = None,
        broker_status: str | None = None,
    ) -> OrderExecution:
        updated = execution.model_copy(
            update={
                "status": status,
                "version": execution.version + 1,
                "alpaca_order_id": alpaca_order_id or execution.alpaca_order_id,
                "broker_status": broker_status or execution.broker_status,
                "updated_at": datetime.now(UTC),
            }
        )
        return self._store.update_order(updated, expected_status=execution.status)

from __future__ import annotations

import asyncio
import logging
from collections.abc import AsyncIterator
from contextlib import asynccontextmanager
from typing import Annotated, cast

from fastapi import Depends, FastAPI, HTTPException, Query, Request
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, ConfigDict

from catalyst_router.challenger import PublicChallengerStatus
from catalyst_router.container import Container
from catalyst_router.domain import (
    AgentMode,
    PublicDecisionPage,
    PublicDecisionRecord,
    PublicPortfolioPoint,
    Route,
)
from catalyst_router.settings import Settings

logger = logging.getLogger(__name__)


class PublicStatus(BaseModel):
    model_config = ConfigDict(extra="forbid")

    mode: AgentMode
    reconciled: bool


def get_container(request: Request) -> Container:
    return cast(Container, request.app.state.container)


ContainerDependency = Annotated[Container, Depends(get_container)]


def create_app(container: Container | None = None) -> FastAPI:
    app_container = container or Container.build(Settings.from_env())

    @asynccontextmanager
    async def lifespan(_: FastAPI) -> AsyncIterator[None]:
        if (
            app_container.settings.runtime_role != "reporting"
            and app_container.settings.auto_reconcile
            and app_container.broker is not None
        ):
            try:
                await asyncio.to_thread(app_container.reconciliation_service().reconcile)
            except Exception:
                logger.exception("startup reconciliation failed; agent remains fenced")
        yield

    app = FastAPI(title="Catalyst Router", version="0.1.0", lifespan=lifespan)
    app.add_middleware(
        CORSMiddleware,
        allow_origins=list(app_container.settings.cors_origins),
        allow_methods=["GET"],
        allow_headers=["Accept"],
    )
    app.state.container = app_container

    @app.get("/health")
    def health() -> dict[str, str]:
        return {"status": "ok"}

    @app.get("/ready")
    def ready(container: ContainerDependency) -> dict[str, str]:
        if not container.store.get_agent_state().is_reconciled:
            raise HTTPException(status_code=503, detail="current execution epoch is unreconciled")
        return {"status": "ready"}

    @app.get("/api/public/status", response_model=PublicStatus)
    def public_status(container: ContainerDependency) -> PublicStatus:
        state = container.store.get_agent_state()
        return PublicStatus(
            mode=state.mode,
            reconciled=state.is_reconciled,
        )

    @app.get("/api/public/decisions", response_model=list[PublicDecisionRecord])
    def public_decisions(
        container: ContainerDependency,
        limit: Annotated[int, Query(ge=1, le=100)] = 50,
    ) -> list[PublicDecisionRecord]:
        return container.store.list_public_decisions(limit)

    @app.get("/api/public/portfolio", response_model=list[PublicPortfolioPoint])
    def public_portfolio(
        container: ContainerDependency,
        limit: Annotated[int, Query(ge=1, le=1000)] = 200,
    ) -> list[PublicPortfolioPoint]:
        return container.store.list_public_portfolio(limit)

    @app.get("/api/public/routes", response_model=list[PublicDecisionRecord])
    def public_routes(
        container: ContainerDependency,
        limit: Annotated[int, Query(ge=1, le=1000)] = 100,
    ) -> list[PublicDecisionRecord]:
        return container.store.list_public_routes(limit)

    @app.get("/api/public/decision-pages", response_model=PublicDecisionPage)
    def public_decision_pages(
        container: ContainerDependency,
        limit: Annotated[int, Query(ge=1, le=100)] = 25,
        cursor: str | None = None,
        search: Annotated[str | None, Query(max_length=100)] = None,
        route: Route | None = None,
        decision_type: Annotated[str | None, Query(max_length=100)] = None,
    ) -> PublicDecisionPage:
        try:
            return container.store.list_public_decision_page(
                limit=limit,
                cursor=cursor,
                search=search,
                route=route,
                decision_type=decision_type,
            )
        except ValueError as error:
            raise HTTPException(status_code=422, detail="invalid decision page cursor") from error

    @app.get("/api/public/challenger", response_model=PublicChallengerStatus)
    def public_challenger(container: ContainerDependency) -> PublicChallengerStatus:
        if container.challenger is None:
            return PublicChallengerStatus.not_deployed()
        return container.challenger.status

    @app.post("/api/operator/reconcile", include_in_schema=False)
    def operator_reconcile() -> None:
        raise HTTPException(status_code=404)

    return app


app = create_app()

